#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LEN 100

typedef struct {
    int id;
    char content[MAX_LEN];
} Word;

int cmp(const void *a, const void *b) {
    return ((Word *) a)->id - ((Word *) b)->id;
}

int main() {
    int n;
    scanf("%d", &n);

    getchar(); // 读取掉第一行结尾的换行符

    Word *words = (Word *) calloc(n, sizeof(Word));
    for (int i = 0; i < n; i++) {
        scanf("%[^0-9]%d", words[i].content, &words[i].id);
        getchar(); // 读取掉空格，换行符
    }

    qsort(words, n, sizeof(Word), cmp);

    char res[100000];
    for (int i = 0; i < n; i++) {
        strcat(res, words[i].content);
        strcat(res, " ");
    }

    // 上面逻辑会在res末尾多拼接一个空格，这里去掉该空格
    res[strlen(res) - 1] = '\0';

    puts(res);

    return 0;
}
